HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPWM Loan Calculator</title><style>
*{box-sizing:border-box}body{margin:0;color:#111;background:white;font:16px/1.5 Arial,sans-serif}main{max-width:1100px;margin:auto;padding:22px;border-top:5px solid #ce2029}header{display:flex;align-items:center;gap:22px;border-bottom:2px solid #ce2029}header img{width:190px;height:auto}h1{font-size:25px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}label{display:block;font-size:14px;font-weight:bold}input:not([type=checkbox]),select,textarea{width:100%;padding:11px;margin-top:6px;border:1px solid #aaa;border-radius:5px;font:16px Arial;color:black;background:white}textarea{min-height:100px}fieldset{margin:20px 0;padding:16px;border:1px solid #ddd}legend{font-weight:bold}button{padding:12px 18px;margin:12px 8px 12px 0;border:0;border-radius:5px;background:#ce2029;color:white;font-weight:bold;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}:focus-visible{outline:3px solid black;outline-offset:3px}.note{padding:14px;background:#f5f5f5;border-left:4px solid #ce2029;font-size:13px}.check{display:flex;align-items:flex-start;gap:10px;font-weight:normal;margin:16px 0}.check input{width:20px;height:20px;flex-shrink:0}#summary p{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #ddd;padding:8px}table{width:100%;border-collapse:collapse;font-size:12px}th{background:black;color:white}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:right;white-space:nowrap}.scroll{overflow:auto}a{color:black}#status,#error{font-weight:bold}[hidden]{display:none!important}@media(max-width:600px){header{flex-direction:column;align-items:flex-start}.grid{grid-template-columns:1fr}#summary p{flex-direction:column}}
</style></head><body><main><header><img src="/logo" alt="SP Wealth Management"><h1>Loan Payoff &amp; Early Settlement Calculator</h1></header><p class="note">Planning estimates for natural-person performing accounts. Actual/365 simple daily interest; entered rate held constant. Payments settle interest, fees, then principal. Not an official lender quotation, financial advice or legal certification.</p>
<form id="loan"><fieldset><legend>1. Loan, fees and insurance</legend><div class="grid" id="fields"></div><p class="note">Use current principal and remaining term for an existing account. Do not add initiation fees again if already included. Final payment clears any residual and balloon; monthly PMT may differ from actual/365 repayments. No first-period fee/insurance proration. Fees entered include applicable VAT.</p></fieldset><fieldset><legend>2. Irregular additional payments</legend><label>One payment per line: YYYY-MM-DD, amount<textarea id="irregular" placeholder="2027-06-15, 10000"></textarea></label><p>These are additional payments, not replacements for scheduled debit orders.</p></fieldset><fieldset><legend>3. Optional documented charges</legend><label>One per line: YYYY-MM-DD, insurance|default|collection, amount<textarea id="fees" placeholder="2027-06-15, insurance, 100"></textarea></label><label class="check"><input id="verified" type="checkbox"><span>I have independently checked entitlement and the applicable tariff/cap for dated charges. No default ledger, legal tariff or section 103(5) reconstruction is provided.</span></label></fieldset><fieldset><legend>4. Settlement estimate (optional)</legend><div id="settlement" class="grid"></div><label class="check"><input id="original_large" type="checkbox"><span>For an existing non-mortgage loan: the original agreement was large even if today's balance is lower.</span></label><p class="note">Settlement is AFTER same-day scheduled/extra payments. Ordinary mortgages are treated as large; other supported transactions use original principal of at least R250,000. Variable large-agreement termination interest is approximated to three calendar months after notice; no notice assumes three months from settlement. Fixed large totals are withheld without the lender-confirmed charge.</p></fieldset><button>Calculate</button><button type="button" id="reset">Clear dated entries / restore sample</button></form><p id="error" role="alert"></p><section id="results" hidden><h2>Your estimate</h2><div id="summary"></div><p id="warnings" class="note"></p><button type="button" id="csv">Download schedule (CSV / Excel compatible)</button><details><summary>Full amortisation schedule</summary><div class="scroll" id="schedule"></div></details></section>
<h2>Email my PDF</h2><p>The server prepares your PDF and sends it to your email address. A PDF copy and internal Excel version are sent separately to webmaster@spwm.co.za. The Excel version is not sent to the client.</p><form id="report"><div class="grid"><label>Full name<input id="name" autocomplete="name" maxlength="120" required></label><label>Email<input id="email" type="email" autocomplete="email" maxlength="254" required></label><label>Mobile (optional)<input id="mobile" type="tel" autocomplete="tel" maxlength="30"></label></div>{% if privacy %}<p><a href="{{ privacy }}" target="_blank" rel="noopener">Read the SPWM privacy notice</a></p>{% endif %}<label class="check"><input id="consent" type="checkbox" required><span>I request this report and agree to processing of my contact and calculation information by SPWM and its service providers to prepare and deliver it, including the SPWM copy. I have read the privacy notice. This is not a marketing subscription.</span></label><label class="check"><input id="followup" type="checkbox"><span>Optional: Please contact me about my calculation.</span></label>{% if enabled %}<div class="cf-turnstile" data-sitekey="{{ sitekey }}" data-action="report"></div>{% else %}<p class="note">Calculator available. Email reporting is disabled until SPWM completes sender, security and privacy configuration.</p>{% endif %}<button id="send" {% if not enabled %}disabled{% endif %}>Email my PDF</button></form><p id="status" role="status" aria-live="polite"></p>
<details><summary>Methodology and limitations</summary><p>Reference screens: service R60 before VAT; unsecured/other supported transactions initiation R165 plus 10% above R1,000 capped R1,050; ordinary mortgage R1,100 plus 10% above R10,000 capped R5,250; proportional 15% screen before VAT. Insurance base single-life rates: ordinary mortgage R2, other supported categories R4.50 per R1,000/month. Fixed premiums need ongoing review. Repo reference offsets: mortgage +12, personal unsecured +21, other transactions +17 percentage points. Check current law, applicable agreements, VAT and product mapping. These are not legal certifications.</p><p>600-month software limit is not a statutory loan limit. No universal NCA maximum principal is claimed. No juristic-person applicability decision, future rate changes, enhanced/joint-life insurance, affordable housing assessment, daily cent rounding, interest-on-interest compounding, default-cap reconstruction, debt review, collection/court tariff validation or conveyancing/bond cancellation attorney fees. Monthly costs billed at scheduled dates. Insurance is already in total fees. CSV contains calculation data only.</p></details><p class="note">SP Wealth Management · webmaster@spwm.co.za · version 3.0.0. Do not enter ID or bank-account numbers. No public PDF download or print button. PDFs are generated in memory; hosting, security and email providers process information under the published privacy/retention arrangements. Email service acceptance does not prove inbox delivery.</p></main>
{% if enabled %}<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script>{% endif %}
<script>
const $=id=>document.getElementById(id);const money=n=>n===null?'Lender-confirmed charge required':new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(n);let reference=crypto.randomUUID();
function field(parent,id,label,value,options,type='number'){const l=document.createElement('label');l.textContent=label;const el=document.createElement(options?'select':'input');el.id=id;if(options){options.forEach(([v,t])=>el.add(new Option(t,v)));el.value=value;}else{el.type=type;el.value=value;if(type==='number'){el.min=0;el.step='any';}}l.append(el);$(parent).append(l);}
const now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');const last=new Date(Date.UTC(now.getFullYear(),now.getMonth()+2,0)).getUTCDate(),first=new Date(Date.UTC(now.getFullYear(),now.getMonth()+1,Math.min(now.getDate(),last))).toISOString().slice(0,10);
field('fields','kind','Loan type','personal',[['personal','Personal loan'],['vehicle','Vehicle finance'],['home','Ordinary home loan']]);[['principal','Principal at balance date (R)',250000],['rate','Nominal annual rate (%)',11.75],['months','Remaining months',60],['payment','Actual monthly instalment excl fees (R), optional',''],['extra','Extra monthly payment (R)',0],['balloon','Vehicle balloon at maturity (R)',0],['service','Monthly service fee incl VAT (R)',69],['initiation','Initiation fee incl VAT (R)',0],['vat','VAT fraction',.15],['repo','Verified applicable repo rate (%), optional',''],['insurance_rate','Credit-life rate per R1,000 (R)',0],['premium','Fixed monthly credit-life premium (R)',0]].forEach(x=>field('fields',...x));field('fields','start','Balance / advance date',today,null,'date');field('fields','first','First scheduled payment date',first,null,'date');field('fields','finance','Initiation fee treatment','false',[['false','Paid upfront'],['true','Financed, not already in balance']]);field('fields','insurance','Credit-life method','none',[['none','No premium modelled'],['fixed','Fixed monthly policy premium'],['reducing','Rate per declining R1,000 principal']]);field('settlement','quote','Requested settlement date','','','date');field('settlement','notice','Date notice received (optional)','','','date');field('settlement','rate_type','Rate type','variable',[['variable','Variable (constant projected rate)'],['fixed','Fixed']]);field('settlement','fixed_charge','Lender-confirmed fixed termination charge (R)','');
const defaults={};document.querySelectorAll('#fields input,#fields select,#settlement input,#settlement select').forEach(x=>defaults[x.id]=x.value);
function lines(id,fee=false){return $(id).value.split(/\n/).filter(x=>x.trim()).map(s=>{const p=s.split(',').map(x=>x.trim());if(p.length!==(fee?3:2))throw Error('Check '+id+' line format.');return fee?{date:p[0],kind:p[1],amount:p[2],verified:$('verified').checked}:{date:p[0],amount:p[1]};});}
function loan(){const c={};document.querySelectorAll('#fields input,#fields select,#settlement input,#settlement select').forEach(x=>c[x.id]=x.value);c.finance=c.finance==='true';c.original_large=$('original_large').checked;c.irregular=lines('irregular');c.fees=lines('fees',true);return c;}
async function post(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let d;try{d=await r.json();}catch(e){throw Error('Service unavailable. Please wait and retry.');}if(!r.ok)throw Error(d.error||'Request failed.');return d;}
function display(r){$('summary').replaceChildren();const pairs=[['Monthly instalment excluding fees',money(r.instalment)],['Payoff date',r.payoff],['Final payment including residual/balloon',money(r.final_payment)],['Total paid',money(r.total_paid)],['Interest',money(r.total_interest)],['Fees including insurance',money(r.total_fees)],['Insurance component (already included)',money(r.total_insurance)],['Interest saved vs no extras',money(r.interest_saved)],['Unused offered payments (not debited)',money(r.unused)]];if(r.quote)Object.entries(r.quote).forEach(([k,v])=>pairs.push(['Settlement '+k,k==='date'?v:money(v)]));pairs.forEach(([k,v])=>{const p=document.createElement('p'),s=document.createElement('span'),b=document.createElement('strong');s.textContent=k;b.textContent=v;p.append(s,b);$('summary').append(p);});$('warnings').textContent=r.warnings.join(' ');const keys=['date','event','interest','fees','payment','capital_paid','principal','balance'],t=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');keys.forEach(k=>{const th=document.createElement('th');th.scope='col';th.textContent=k;tr.append(th);});head.append(tr);t.append(head);const body=document.createElement('tbody');r.rows.forEach(row=>{const tr=document.createElement('tr');keys.forEach(k=>{const td=document.createElement('td');td.textContent=typeof row[k]==='number'?money(row[k]):row[k];tr.append(td);});body.append(tr);});t.append(body);$('schedule').replaceChildren(t);$('results').hidden=false;}
$('loan').addEventListener('input',()=>{reference=crypto.randomUUID();$('results').hidden=true;});$('report').addEventListener('input',()=>{reference=crypto.randomUUID();});
$('loan').onsubmit=async e=>{e.preventDefault();$('error').textContent='';$('results').hidden=true;try{display(await post('/calculate',{loan:loan()}));}catch(x){$('error').textContent=x.message;}};
$('reset').onclick=()=>{Object.entries(defaults).forEach(([k,v])=>$(k).value=v);$('verified').checked=false;$('original_large').checked=false;$('irregular').value='';$('fees').value='';$('results').hidden=true;reference=crypto.randomUUID();$('error').textContent='';};
$('csv').onclick=async()=>{try{const r=await fetch('/csv',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({loan:loan()})});if(!r.ok)throw Error('Export failed. Recalculate and retry.');const u=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=u;a.download='SPWM-schedule.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(x){$('error').textContent=x.message;}};
$('report').onsubmit=async e=>{e.preventDefault();const b=$('send');b.disabled=true;$('status').textContent='Preparing your report…';try{const c=loan();display(await post('/calculate',{loan:c}));const token=document.querySelector('[name="cf-turnstile-response"]')?.value||'';const r=await post('/email',{loan:c,request_id:reference,token,person:{name:$('name').value,email:$('email').value,mobile:$('mobile').value,consent:$('consent').checked,followup:$('followup').checked}});$('status').textContent=r.message+' Reference: '+r.reference;}catch(x){$('status').textContent=x.message;}finally{b.disabled=false;if(window.turnstile)turnstile.reset();}};
new ResizeObserver(()=>{try{const origin=new URL(document.referrer).origin;if(['https://www.spwm.co.za','https://spwm.co.za'].includes(origin))parent.postMessage({type:'spwm-height',height:document.querySelector('main').scrollHeight+44},origin);}catch(e){}}).observe(document.querySelector('main'));
</script></body></html>'''
